 "content": "from collections import Counter


def transform(grid):
    """Compare corresponding cells in the two panels around a solid divider."""
    h, w = len(grid), len(grid[0])
    panels = None
    # A divider must be a full uniform line and leave equal-sized panels.
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1 and r == h - r - 1:
            panels = ([row[:] for row in grid[:r]], [row[:] for row in grid[r + 1:]])
            break
    if panels is None:
        for c in range(1, w - 1):
            if all(row[c] == grid[0][c] for row in grid) and c == w - c - 1:
                panels = ([row[:c] for row in grid], [row[c + 1:] for row in grid])
                break
    if panels is None:
        raise ValueError("expected centered solid divider between equal panels")
    a, b = panels
    ca, cb = Counter(v for row in a for v in row), Counter(v for row in b for v in row)
    shared = set(ca) & set(cb)
    # The shared panel color is the one with fewest occurrences on either side;
    # in these paired noise fields it is the common background color.
    color = min(shared, key=lambda v: (max(ca[v], cb[v]), ca[v] + cb[v]))
    return [[3 if x == color and y == color else color
             for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]


if __name__ == "__main__":
    pass
